function PTSC_HPH_ClearNotes(last)
	local i = 42
	while i <= last do
		TaskNote(i, -1)
		i = i + 1
	end
end

-- solo Dao ly graduation: apprentice part of shengxian_end_P + master part of shengxian_end_M for the player
function PTSC_HPH_SoloEnd()
	if (PTSC_Ready() ~= 1) or (PTSC_IsSolo() ~= 1) then
		CloseDialog()
		return
	end
	if (GetTask(PTSC_T_GRAD) ~= 0) or (GetLevel() < 50) or (GetTask(905) ~= 9) or (step_complete() < 2) then
		Talk(1, "no", "Ng\173\172i \174\183 xu\202t s\173 r\229i, nghi l\212 n\181y ch\216 l\181m m\233t l\199n.")
		return
	end
	SetTask(PTSC_T_GRAD, 1)
	UnMasterPREx("")
	local exp = GetNextExp() - GetExp()
	if 1000000 >= exp then
		AddOwnExp(exp)
		AddOwnExp(1000000 - exp)
	else
		AddOwnExp(1000000)
	end
	if GetTask(903) == 0 then
		AddNormalItem(0, 4, 33, 1, 0, 0)
	end
	local i = 895
	while i <= 907 do
		SetTask(i, 0)
		i = i + 1
	end
	SetTask(903, 1)
	RemoveIBBuff(217)
	PTSC_HPH_ClearNotes(47)
	AddMasterPRValue(PTSC_SOLO_DAOLY_POINTS)
	Msg2Player("Ho\181n t\202t xu\202t s\173. Ho\181ng Phi H\230 thay s\173 ph\244 trao cho b\185n 15 \174i\211m s\173 \174\229!")
	AddGlobalCountNews("<color=green>" .. GetName() .. "<color> thu\203n l\238i xu\202t s\173, Ho\181ng Phi H\230 t\198ng <color=green>L\173\236ng Nghi Quy Ch\169n K\221nh<color>.", 20)
	CloseDialog()
end

